// Charts generated by an independent site (onlinejyotish.com) from made-up birth data: tests/fixtures/charts-published.json.
// The site prints positions truncated to the arcminute, so AstroZ's longitude must lie in [printed − 0.01°, printed + 1′ + 0.01°]
// (the Phase 2 ±0.01° tolerance around the truncation interval). Dasha dates are printed to the day and must match exactly.
import { describe, expect, it } from 'vitest';
import fixture from '../../fixtures/charts-published.json';
import { createEngine } from '../../../src/engine/core/engine';
import { loadEphemeris } from '../../../src/engine/ephemeris';

const engine = createEngine(() => loadEphemeris());
const TOL = 0.01; // degrees (SPEC §9 Phase 2)
const MINUTE = 1 / 60;
const ahead = (ours: number, printed: number) => ((ours - printed + 540) % 360) - 180; // signed degrees
const inTruncation = (ours: number, printed: number) => { const d = ahead(ours, printed); return d >= -TOL && d < MINUTE + TOL; };
const rasiOf = (lon: number) => Math.floor(lon / 30) + 1;

describe('published charts (tests/fixtures/charts-published.json)', () => {
  const unverified = fixture.rows.filter((r) => !r.verified).map((r) => r.id);
  if (unverified.length) it.todo(`a person should confirm against a pandit-made jatakam: ${unverified.join(', ')}`);

  for (const r of fixture.rows) {
    const p = r.published;
    it(`${r.id} · ${r.place.nameEn} ${r.birth.date} ${r.birth.time}`, async () => {
      const c = await engine.birthChart({ date: r.birth.date, time: r.birth.time, timeKnown: true, place: { lat: r.place.lat, lon: r.place.lon, tz: r.place.tz } });
      expect({ rasi: c.moon.rasi, nakshatra: c.moon.nakshatra, pada: c.moon.pada }, 'moon').toEqual({ rasi: rasiOf(p.moon.longitude), nakshatra: p.moon.nakshatra, pada: p.moon.pada });
      expect(inTruncation(c.moon.longitude, p.moon.longitude), `moon ${(ahead(c.moon.longitude, p.moon.longitude) * 60).toFixed(2)}′`).toBe(true);
      expect(c.lagna!.rasi, 'lagna rasi').toBe(rasiOf(p.lagna.longitude));
      expect(inTruncation(c.lagna!.longitude, p.lagna.longitude), `lagna ${(ahead(c.lagna!.longitude, p.lagna.longitude) * 60).toFixed(2)}′`).toBe(true);
      for (const [body, want] of Object.entries(p.planets)) {
        const got = c.planets[body as keyof typeof c.planets];
        expect(got.rasi, `${body} rasi`).toBe(rasiOf(want.longitude));
        expect(inTruncation(got.longitude, want.longitude), `${body} ${(ahead(got.longitude, want.longitude) * 60).toFixed(2)}′`).toBe(true);
      }
      // Dasha: first lord, then the running mahadasha and antardasha on the date the site was read — to the day.
      expect(c.dasha.mahadashas[0]!.lord, 'first dasha lord').toBe(p.dasha.firstLord);
      const at = p.dasha.at;
      const maha = c.dasha.mahadashas.find((m) => m.start.date <= at && at < m.end.date)!;
      const antar = maha.antardashas.find((m) => m.start.date <= at && at < m.end.date)!;
      expect({ lord: maha.lord, start: maha.start.date, end: maha.end.date }, 'mahadasha').toEqual(p.dasha.mahadasha);
      expect({ lord: antar.lord, start: antar.start.date, end: antar.end.date }, 'antardasha').toEqual(p.dasha.antardasha);
      // The printed balance is years/months/days; a month's length is not stated, so only check it to within 2 days.
      const b = p.dasha.balance;
      expect(Math.abs(c.dasha.balanceYears - (b.years + b.months / 12 + b.days / 365.25)) * 365.25, 'balance (days)').toBeLessThanOrEqual(2);
    });
  }
});
